constexpr std::uint64_t kGuestBase = 0x1000000000ULL;

int FakeWebP103Version() { return 0x010003; }

int FakeWebPWrongVersion() { return 0x010004; }

std::uint8_t* FakeWebP103Decode(
    const std::uint8_t* input, std::size_t input_size,
    std::uint8_t* output, std::size_t output_size, int output_stride) {
    if (input == nullptr || input_size != 4 || output == nullptr ||
        output_size != 12 || output_stride != 4 || input[0] == 0xff)
        return nullptr;
    output[0] = input[0];
    output[1] = input[1];
    output[2] = input[2];
    output[3] = input[3];
    output[4] = static_cast<std::uint8_t>(output_stride);
    output[5] = 0x31;
    output[6] = 0x30;
    output[7] = 0x33;
    return output;
}

bool WriteFixture(const std::wstring& path,
                  const std::vector<std::uint8_t>& bytes) {
    HANDLE file = CreateFileW(path.c_str(), GENERIC_WRITE, 0, nullptr,
                              CREATE_ALWAYS, FILE_ATTRIBUTE_TEMPORARY, nullptr);
    if (file == INVALID_HANDLE_VALUE) return false;
    DWORD written = 0;
    const bool ok = bytes.size() <= MAXDWORD &&
                    WriteFile(file, bytes.data(),
                              static_cast<DWORD>(bytes.size()), &written,
                              nullptr) != FALSE &&
                    written == bytes.size();
    CloseHandle(file);
    return ok;
}

bool ReadFixture(const std::wstring& path,
                 const std::vector<std::uint8_t>& expected) {
    HANDLE file = CreateFileW(
        path.c_str(), GENERIC_READ,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
        OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) return false;
    LARGE_INTEGER size{};
    std::vector<std::uint8_t> actual(expected.size());
    DWORD read = 0;
    const bool ok =
        GetFileSizeEx(file, &size) != FALSE &&
        size.QuadPart == static_cast<LONGLONG>(expected.size()) &&
        expected.size() <= MAXDWORD &&
        (expected.empty() ||
         (ReadFile(file, actual.data(), static_cast<DWORD>(actual.size()),
                   &read, nullptr) != FALSE &&
          read == actual.size())) &&
        actual == expected;
    CloseHandle(file);
    return ok;
}

struct MountPointReparseBuffer {
    ULONG reparse_tag = 0;
    USHORT reparse_data_length = 0;
    USHORT reserved = 0;
    USHORT substitute_name_offset = 0;
    USHORT substitute_name_length = 0;
    USHORT print_name_offset = 0;
    USHORT print_name_length = 0;
    wchar_t path_buffer[1]{};
};

static_assert(offsetof(MountPointReparseBuffer, path_buffer) == 16);

bool CreateDirectoryJunction(const std::wstring& link,
                             const std::wstring& target) {
    if (!CreateDirectoryW(link.c_str(), nullptr)) return false;
    HANDLE handle = CreateFileW(
        link.c_str(), GENERIC_WRITE, 0, nullptr, OPEN_EXISTING,
        FILE_FLAG_OPEN_REPARSE_POINT | FILE_FLAG_BACKUP_SEMANTICS, nullptr);
    if (handle == INVALID_HANDLE_VALUE) {
        RemoveDirectoryW(link.c_str());
        return false;
    }

    const std::wstring substitute_name = L"\\??\\" + target;
    const std::size_t substitute_bytes =
        substitute_name.size() * sizeof(wchar_t);
    const std::size_t print_bytes = target.size() * sizeof(wchar_t);
    const std::size_t path_bytes =
        substitute_bytes + sizeof(wchar_t) +
        print_bytes + sizeof(wchar_t);
    constexpr std::size_t kMountPointFieldsSize =
        sizeof(USHORT) * 4;
    if (path_bytes >
        (std::numeric_limits<USHORT>::max)() -
            kMountPointFieldsSize) {
        CloseHandle(handle);
        RemoveDirectoryW(link.c_str());
        return false;
    }

    const std::size_t header_size =
        offsetof(MountPointReparseBuffer, path_buffer);
    std::vector<std::uint8_t> buffer(header_size + path_bytes);
    auto* reparse =
        reinterpret_cast<MountPointReparseBuffer*>(buffer.data());
    reparse->reparse_tag = IO_REPARSE_TAG_MOUNT_POINT;
    reparse->reparse_data_length = static_cast<USHORT>(
        kMountPointFieldsSize + path_bytes);
    reparse->substitute_name_length =
        static_cast<USHORT>(substitute_bytes);
    reparse->print_name_offset = static_cast<USHORT>(
        substitute_bytes + sizeof(wchar_t));
    reparse->print_name_length = static_cast<USHORT>(print_bytes);
    std::memcpy(reparse->path_buffer, substitute_name.c_str(),
                substitute_bytes + sizeof(wchar_t));
    std::memcpy(
        reinterpret_cast<std::uint8_t*>(reparse->path_buffer) +
            reparse->print_name_offset,
        target.c_str(), print_bytes + sizeof(wchar_t));

    DWORD returned = 0;
    const bool created =
        buffer.size() <= MAXDWORD &&
        DeviceIoControl(
            handle, FSCTL_SET_REPARSE_POINT, buffer.data(),
            static_cast<DWORD>(buffer.size()), nullptr, 0, &returned,
            nullptr) != FALSE;
    CloseHandle(handle);
    if (!created) RemoveDirectoryW(link.c_str());
    return created;
}

std::optional<std::wstring> TemporaryFixturePath() {
    std::array<wchar_t, MAX_PATH + 1> directory{};
    const DWORD length = GetTempPathW(static_cast<DWORD>(directory.size()),
                                      directory.data());
    if (length == 0 || length >= directory.size()) return std::nullopt;
    std::array<wchar_t, MAX_PATH + 1> path{};
    if (GetTempFileNameW(directory.data(), L"iso", 0, path.data()) == 0)
        return std::nullopt;
    return std::wstring(path.data());
}

class FixtureFile {
public:
    explicit FixtureFile(std::wstring path) : path_(std::move(path)) {}
    ~FixtureFile() { DeleteFileW(path_.c_str()); }
    const std::wstring& path() const { return path_; }

private:
    std::wstring path_;
};

class FixtureDirectory {
public:
    static std::optional<FixtureDirectory> Create() {
        const std::optional<std::wstring> candidate = TemporaryFixturePath();
        if (!candidate || !DeleteFileW(candidate->c_str()) ||
            !CreateDirectoryW(candidate->c_str(), nullptr))
            return std::nullopt;
        return FixtureDirectory(*candidate);
    }

    FixtureDirectory(FixtureDirectory&& other) noexcept
        : path_(std::move(other.path_)) {
        other.path_.clear();
    }
    FixtureDirectory& operator=(FixtureDirectory&&) = delete;
    ~FixtureDirectory() {
        if (path_.empty()) return;
        DeleteFileW((path_ + L"\\assets\\asset.bin").c_str());
        RemoveDirectoryW((path_ + L"\\assets").c_str());
        DeleteFileW((path_ + L"\\data\\state.bin").c_str());
        DeleteFileW((path_ + L"\\data\\writable.bin").c_str());
        DeleteFileW((path_ + L"\\data\\reuse-target.bin").c_str());
        DeleteFileW((path_ + L"\\data\\created\\remove.bin").c_str());
        DeleteFileW((path_ + L"\\data\\created\\caf\u00e9.bin").c_str());
        DeleteFileW(
            (path_ + L"\\data\\created\\nonempty\\keep.bin").c_str());
        RemoveDirectoryW((path_ + L"\\data\\created\\empty").c_str());
        RemoveDirectoryW((path_ + L"\\data\\created\\nonempty").c_str());
        RemoveDirectoryW(
            (path_ + L"\\data\\outside-link").c_str());
        RemoveDirectoryW((path_ + L"\\data\\created").c_str());
        RemoveDirectoryW((path_ + L"\\data").c_str());
        for (const wchar_t* name : {L"consumer.so", L"libprovider.so",
                                    L"unsafe.so", L"cycle-a.so",
                                    L"cycle-b.so", L"asset.bin",
                                    L"victim.bin", L"new.bin",
                                    L"telemetry #.so"})
            DeleteFileW((path_ + L"\\" + name).c_str());
        RemoveDirectoryW(path_.c_str());
    }
    const std::wstring& path() const { return path_; }
    std::wstring File(const wchar_t* name) const {
        return path_ + L"\\" + name;
    }

private:
    explicit FixtureDirectory(std::wstring path) : path_(std::move(path)) {}
    std::wstring path_;
};

class Callbacks final : public A64::UserCallbacks {
public:
    enum class MemoryCaptureKind {
        kNone,
        kRead,
        kWrite,
    };

    Callbacks(isomr::Elf64Image* image, std::uint64_t terminal_address,
              const isomr::Aarch64ImportRegistry* imports = nullptr,
              isomr::GuestHeap* heap = nullptr)
        : image_(image), imports_(imports), heap_(heap),
          terminal_address_(terminal_address) {}
    Callbacks(isomr::Elf64ModuleSet* modules,
              std::uint64_t terminal_address,
              const isomr::Aarch64ImportRegistry* imports = nullptr,
              isomr::GuestHeap* heap = nullptr)
        : modules_(modules), imports_(imports), heap_(heap),
          terminal_address_(terminal_address) {}
    void Attach(A64::Jit* jit) { jit_ = jit; }
    void ArmMemoryCapture(MemoryCaptureKind kind, std::uint64_t address,
                          std::size_t size) {
        capture_kind_ = kind;
        capture_address_ = address;
        capture_size_ = size;
        capture_triggered_ = false;
        capture_callback_program_counter_ = 0;
    }
    bool memory_capture_triggered() const { return capture_triggered_; }
    std::uint64_t capture_callback_program_counter() const {
        return capture_callback_program_counter_;
    }

    std::optional<std::uint32_t> MemoryReadCode(
        std::uint64_t address) override {
        std::uint32_t value = 0;
        if (imports_ != nullptr && address >= imports_->guest_base() &&
            address < imports_->guest_base() + imports_->code_size()) {
            if (!imports_->ReadCode(address, &value, sizeof(value)))
                return std::nullopt;
            return value;
        }
        if (!ReadCodeMemory(address, &value, sizeof(value))) {
            valid_ = false;
            return std::nullopt;
        }
        return value;
    }
    std::uint8_t MemoryRead8(std::uint64_t address) override {
        return Read<std::uint8_t>(address);
    }
    std::uint16_t MemoryRead16(std::uint64_t address) override {
        return Read<std::uint16_t>(address);
    }
    std::uint32_t MemoryRead32(std::uint64_t address) override {
        return Read<std::uint32_t>(address);
    }
    std::uint64_t MemoryRead64(std::uint64_t address) override {
        return Read<std::uint64_t>(address);
    }
    A64::Vector MemoryRead128(std::uint64_t address) override {
        A64::Vector value{};
        if (!ReadMemory(address, value.data(), sizeof(value))) Abort();
        return value;
    }
    void MemoryWrite8(std::uint64_t address, std::uint8_t value) override {
        Write(address, value);
    }
    void MemoryWrite16(std::uint64_t address, std::uint16_t value) override {
        Write(address, value);
    }
    void MemoryWrite32(std::uint64_t address, std::uint32_t value) override {
        Write(address, value);
    }
    void MemoryWrite64(std::uint64_t address, std::uint64_t value) override {
        Write(address, value);
    }
    void MemoryWrite128(std::uint64_t address, A64::Vector value) override {
        if (!WriteMemory(address, value.data(), sizeof(value))) Abort();
    }

    void InterpreterFallback(std::uint64_t address, std::size_t) override {
        StopOrAbort(address);
    }
    void CallSVC(std::uint32_t immediate) override {
        const std::uint64_t pc = jit_->GetPC();
        const bool registry_stub =
            imports_ != nullptr && pc >= imports_->guest_base() &&
            pc < imports_->guest_base() + imports_->code_size();
        if (immediate == 7 && !registry_stub) {
            jit_->SetRegister(0, jit_->GetRegister(0) * 2);
            return;
        }
        if (imports_ == nullptr) {
            Abort();
            return;
        }
        isomr::Aarch64ImportRegistry::Registers registers{};
        for (std::size_t index = 0; index < registers.size(); ++index) {
            registers[index] = jit_->GetRegister(index);
            registers.vector[index] = jit_->GetVector(index);
        }
        registers.stack_pointer = jit_->GetSP();
        std::string error;
        if (!imports_->Dispatch(immediate, &registers, &error)) {
            Abort();
            return;
        }
        for (std::size_t index = 0; index < registers.size(); ++index) {
            jit_->SetRegister(index, registers[index]);
            jit_->SetVector(index, registers.vector[index]);
        }
    }
    void ExceptionRaised(std::uint64_t address, A64::Exception) override {
        StopOrAbort(address);
    }
    void AddTicks(std::uint64_t) override {}
    std::uint64_t GetTicksRemaining() override { return 1000000ULL; }
    std::uint64_t GetCNTPCT() override { return 0; }
    bool valid() const { return valid_ && stopped_; }

private:
    template <typename T>
    T Read(std::uint64_t address) {
        T value{};
        if (!ReadMemory(address, &value, sizeof(value))) {
            Abort();
        } else {
            CaptureMemoryAccess(MemoryCaptureKind::kRead, address,
                                sizeof(value));
        }
        return value;
    }

    template <typename T>
    void Write(std::uint64_t address, T value) {
        if (!WriteMemory(address, &value, sizeof(value))) {
            Abort();
        } else {
            CaptureMemoryAccess(MemoryCaptureKind::kWrite, address,
                                sizeof(value));
        }
    }

    void CaptureMemoryAccess(MemoryCaptureKind kind, std::uint64_t address,
                             std::size_t size) {
        if (capture_triggered_ || capture_kind_ != kind ||
            size == 0 || capture_size_ == 0 ||
            address > std::numeric_limits<std::uint64_t>::max() - size ||
            capture_address_ >
                std::numeric_limits<std::uint64_t>::max() - capture_size_ ||
            address + size <= capture_address_ ||
            capture_address_ + capture_size_ <= address)
            return;
        capture_triggered_ = true;
        capture_callback_program_counter_ = jit_ != nullptr ? jit_->GetPC() : 0;
        if (jit_ != nullptr)
            jit_->HaltExecution(Dynarmic::HaltReason::MemoryAbort);
    }

    bool ReadMemory(std::uint64_t address, void* destination,
                    std::size_t size) {
        if (heap_ != nullptr && heap_->ContainsAddress(address))
            return heap_->Read(address, destination, size);
        return modules_ != nullptr
                   ? modules_->Read(address, destination, size)
                   : image_->Read(address, destination, size);
    }

    bool ReadCodeMemory(std::uint64_t address, void* destination,
                        std::size_t size) {
        return modules_ != nullptr
                   ? modules_->ReadCode(address, destination, size)
                   : image_->ReadCode(address, destination, size);
    }

    bool WriteMemory(std::uint64_t address, const void* source,
                     std::size_t size) {
        if (heap_ != nullptr && heap_->ContainsAddress(address))
            return heap_->Write(address, source, size);
        return modules_ != nullptr
                   ? modules_->Write(address, source, size)
                   : image_->Write(address, source, size);
    }

    void Abort() {
        valid_ = false;
        if (jit_ != nullptr)
            jit_->HaltExecution(Dynarmic::HaltReason::MemoryAbort);
    }

    void StopOrAbort(std::uint64_t address) {
        if (address != terminal_address_) {
            Abort();
            return;
        }
        stopped_ = true;
        jit_->HaltExecution(Dynarmic::HaltReason::MemoryAbort);
    }

    isomr::Elf64Image* image_ = nullptr;
    isomr::Elf64ModuleSet* modules_ = nullptr;
    const isomr::Aarch64ImportRegistry* imports_ = nullptr;
    isomr::GuestHeap* heap_ = nullptr;
    std::uint64_t terminal_address_;
    A64::Jit* jit_ = nullptr;
    MemoryCaptureKind capture_kind_ = MemoryCaptureKind::kNone;
    std::uint64_t capture_address_ = 0;
    std::size_t capture_size_ = 0;
    bool capture_triggered_ = false;
    std::uint64_t capture_callback_program_counter_ = 0;
    bool valid_ = true;
    bool stopped_ = false;
};

template <typename T>
bool ReadValue(const isomr::Elf64Image& image, std::uint64_t virtual_address,
               T* value) {
    const auto guest = image.GuestAddress(virtual_address);
    return guest && image.Read(*guest, value, sizeof(T));
}

int Fail(const char* stage) {
    std::fprintf(stderr, "ISOMR_ELF64 failure=%s\n", stage);
    return 1;
}

int TestAarch64SessionWorkerSlices(
    isomr::Elf64ModuleSet* modules,
    isomr::Aarch64ImportRegistry* imports,
    isomr::GuestHeap* heap,
    std::uint64_t thread_pointer,
    std::uint64_t bounded_loop,
    std::uint64_t infinite_loop) {
    std::array<std::uint64_t, 8> arguments{};
    arguments[0] = 1024;
    std::uint64_t result = UINT64_MAX;
    std::string error;
    auto renewable_session = isomr::Aarch64GuestSession::Create(
        modules, imports, heap, thread_pointer, 16 * 1024, 32, &error);
    std::size_t renewable_callbacks = 0;
    const bool renewable_sliced =
        renewable_session &&
        renewable_session->SetOwnerThreadInterSliceCallback(
            8,
            [&](std::string*) {
                ++renewable_callbacks;
                return true;
            },
            &error,
            /*renew_total_budget_after_slice=*/true);
    const bool renewable_call =
        renewable_sliced &&
        renewable_session->Call(bounded_loop, arguments, &result, &error);
    if (!renewable_call || result != 0 || renewable_callbacks < 2)
        return Fail("aarch64-session-worker-slice-renew");
    renewable_session.reset();

    auto cancellation_requested =
        std::make_shared<std::atomic<bool>>(false);
    auto cancellation_observed =
        std::make_shared<std::atomic<bool>>(false);
    isomr::Aarch64GuestProcessExitCancellation cancellation;
    cancellation.requested = [cancellation_requested] {
        return cancellation_requested->load(std::memory_order_acquire);
    };
    cancellation.observed = [cancellation_observed] {
        cancellation_observed->store(true, std::memory_order_release);
    };
    auto cancellation_session = isomr::Aarch64GuestSession::Create(
        modules, imports, heap, thread_pointer, 16 * 1024, 32, &error, {},
        {}, std::move(cancellation));
    std::size_t cancellation_callbacks = 0;
    const bool cancellation_configured =
        cancellation_session &&
        cancellation_session->SetOwnerThreadInterSliceCallback(
            8,
            [&](std::string*) {
                ++cancellation_callbacks;
                cancellation_requested->store(
                    true, std::memory_order_release);
                return true;
            },
            &error,
            /*renew_total_budget_after_slice=*/true);
    error.clear();
    const bool cancellation_call =
        cancellation_configured &&
        cancellation_session->Call(infinite_loop, {}, &result, &error);
    if (cancellation_call ||
        error.find("guest call cancelled for process exit") ==
            std::string::npos ||
        cancellation_callbacks == 0 ||
        !cancellation_observed->load(std::memory_order_acquire))
        return Fail("aarch64-session-worker-slice-cancel");
    cancellation_session.reset();
    return 0;
}

int TestAarch64ProfileWorkerLifetimeSlices() {
    const std::optional<std::wstring> temporary = TemporaryFixturePath();
    if (!temporary) return Fail("aarch64-profile-worker-slice-fixture-path");
    FixtureFile fixture(*temporary);
    if (!WriteFixture(fixture.path(),
                      isomr::test::MakeElf64ThreadStartFixture()))
        return Fail("aarch64-profile-worker-slice-fixture-write");
    isomr::Aarch64ProfileRuntimeConfig config;
    config.heap_base = 0x724000000000ULL;
    config.heap_capacity = 64 * 1024;
    config.import_base = 0x694000000000ULL;
    config.first_module_base = 0x4740000000ULL;
    config.stack_size = 16 * 1024;
    config.instruction_budget = 32;
    isomr::Aarch64ProfileRuntime runtime(std::move(config));
    std::string error;
    const bool loaded =
        runtime.Load(fixture.path(), &error) &&
        runtime.RunInitializers(&error);
    std::uint64_t bounded_loop = 0;
    std::uint64_t infinite_loop = 0;
    const std::array<std::uint32_t, 3> bounded_signature{
        0xf1000400U, 0x54ffffe1U, 0xd65f03c0U};
    const std::array<std::uint32_t, 1> infinite_signature{0x14000000U};
    if (!loaded ||
        !runtime.ResolveGuestModuleCodeOffset(
            {}, isomr::test::kFixtureThreadBoundedLoop,
            bounded_signature, &bounded_loop, &error) ||
        !runtime.ResolveGuestModuleCodeOffset(
            {}, isomr::test::kFixtureThreadLoop,
            infinite_signature, &infinite_loop, &error))
        return Fail("aarch64-profile-worker-slice-address");
    isomr::GuestHeap& heap = runtime.bionic()->heap();
    const std::uint64_t output =
        heap.Callocate(2, sizeof(std::uint64_t));
    if (output == 0) return Fail("aarch64-profile-worker-slice-output");
    std::uint64_t handle = 0;
    std::uint64_t result = UINT64_MAX;
    const bool worker_ok =
        runtime.bionic()->threads().Create(
            output, 0, bounded_loop, 1024) == 0 &&
        heap.Read(output, &handle, sizeof(handle)) &&
        handle != 0 &&
        runtime.bionic()->threads().Join(
            handle, output + sizeof(std::uint64_t)) == 0 &&
        heap.Read(output + sizeof(std::uint64_t), &result,
                  sizeof(result)) &&
        result == 0 &&
        runtime.bionic()->threads().thread_count() == 0 &&
        runtime.bionic()->threads().active_count() == 0 &&
        heap.Release(output, &error);
    if (!worker_ok) return Fail("aarch64-profile-worker-lifetime-slice");

    const std::uint64_t cancel_output =
        heap.Callocate(1, sizeof(std::uint64_t));
    if (cancel_output == 0)
        return Fail("aarch64-profile-worker-slice-cancel-output");
    error.clear();
    const int cancel_create = runtime.bionic()->threads().Create(
        cancel_output, 0, infinite_loop, 0);
    const ULONGLONG cancel_deadline = GetTickCount64() + 2000;
    while (cancel_create == 0 &&
           runtime.bionic()->threads().active_count() == 0 &&
           GetTickCount64() < cancel_deadline)
        SwitchToThread();
    isomr::BionicThreads::ProcessExitWorkerCleanup cleanup;
    const bool cancelled =
        cancel_create == 0 &&
        runtime.bionic()->threads().active_count() == 1 &&
        runtime.bionic()->threads().CancelAndReapWorkersForProcessExit(
            [] { return std::size_t{0}; },
            std::chrono::seconds(2), &cleanup, &error) &&
        cleanup.cancellation_requests == 1 &&
        cleanup.cancellation_observed == 1 &&
        cleanup.workers_reaped == 1 &&
        runtime.bionic()->threads().thread_count() == 0 &&
        runtime.bionic()->threads().active_count() == 0 &&
        runtime.bionic()->threads().CheckCompletedWorkerFailure(&error) &&
        error.empty() &&
        heap.Release(cancel_output, &error);
    if (!cancelled ||
        !runtime.Shutdown(&error) ||
        heap.allocation_count() != 0)
        return Fail("aarch64-profile-worker-slice-cancel");
    std::puts(
        "ISOMR_AARCH64_PROFILE_WORKER_LIFETIME_SLICE bounded=1024 "
        "budget=32 renew=pass cancel=pass cleanup=pass");
    return 0;
}

